  if (!utc) return '';
  const d = new Date(utc.includes('Z') ? utc : utc + 'Z');
  // Convert to Mexico City time zone (UTC-6 for standard time, UTC-5 for DST)
  // Hermosillo is UTC-7 all year round.
  const hermosilloOffset = 7 * 60 * 60 * 1000; // 7 hours in milliseconds
  return new Date(d.getTime() - hermosilloOffset).toLocaleString();
};

