      setItems(newItems);
      setInfiniteScrollDisabled(true); // Disable if we fetched all items at once, adjust if API supports pagination
    } catch (err) {
      setError((err as Error).message ?? 'Error desconocido al cargar recompensas.');
    } finally {
      setLoading(false);
    }
  };

  useIonViewWillEnter(() => {
    fetchItems();
  });

  const handleCreate = () => {
    setIsEditing(false);
    setCurrentItem(null);
    setFormState({
      companyId: companyId,
      name: '',
      rewardType: 'discount',
      requiredPoints: 0,
      discountValue: null,
      freeProductId: null,
      isActive: true,
      description: null,
