                <IonIcon icon={trashOutline} />
              </IonButton>
            </IonItem>
          ))}
        </IonList>

        <IonInfiniteScroll onIonInfinite={loadMoreItems} threshold="100px" disabled={infiniteScrollDisabled}>
          <IonInfiniteScrollContent loadingSpinner="crescent" loadingText="Cargando más recompensas..."></IonInfiniteScrollContent>
